-- Lexicographic Batch 02 (Lots): precision and source-attributed historical additions.
-- Evidence directly checked: Abu Mashar Great Introduction VIII.4.11,4.22-4.25,4.43,4.59,4.77,5.8-5.9,6.8; al-Biruni Book of Instruction §475.
-- Existing Bonatti claims outside this spot-check are not revised or presented as freshly verified.
-- This correction seed does not change formula tables, aliases, ontology, interpretations or source passages.
PRAGMA foreign_keys=ON;

-- Intro passages which simply repeat the indexed short definition. All public technical tables and source accounts remain.
UPDATE term_articles SET intro='',editorial_notes='Batch 02: canonical short definition supplies the headword identity; redundant overview suppressed.' WHERE term_id IN (SELECT id FROM terms WHERE slug IN ('lot','lot-of-siblings','lot-of-children','lot-of-friends','lot-of-daughters','lot-of-sons','lot-of-substance','lot-of-necessity','lot-of-eros','lot-extraction','lot-of-the-haylaj','natural-indicators-of-a-lot','planetary-lots','lot-of-absence','egyptian-lot-of-necessity','persian-lot-of-necessity'));

UPDATE term_articles SET intro='In Abū Maʿshar''s report of a Hermetic procedure, this lot is used as a timing testimony only where the nativity already gives an indication of marriage. The calculation is the same by day and night (Great Introduction VIII.4.43).',editorial_notes='Batch 02: distinct historical context following canonical definition.' WHERE term_id=(SELECT id FROM terms WHERE slug='hermes-lot-of-time-of-marriage');
UPDATE term_articles SET intro='Abū Maʿshar assigns the Sun the principal indications of status and authority by day, and the Moon an analogous role by night. His high-rank lot therefore uses each luminary''s own exaltation degree instead of reversing one fixed planetary pair (Great Introduction VIII.4.59).',editorial_notes='Batch 02: distinct historical context following canonical definition.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-rank');
UPDATE term_articles SET intro='Abū Maʿshar describes Fortune and Absence as the two luminary lots, but the order of their components and even their names vary between traditions. Al-Bīrūnī reports both the unreversed calculation attributed to Ptolemy and a night-reversed practice used by other authors (Book of Instruction §475).',editorial_notes='Batch 02: distinct historical context following canonical definition.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-fortune');

UPDATE term_article_sections SET heading='Reading a Lot formula',body='In the notation Asc + B − A, take the zodiacal distance from A to B and add that distance to the longitude of the Ascendant. The resulting degree is the Lot. Some transmitted procedures reverse the interval by sect or start from a different point; those changes belong to the particular formula being cited.',editorial_notes='Lexicographic Batch 02: source-aware explanatory prose; formula tables preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot') AND section_key='notation';
UPDATE term_article_sections SET heading='Lot and Part',body='Lot and Part are common English names for a family of calculated points, corresponding to terms such as the Arabic sahm and Latin pars. A different English rendering does not by itself create a second calculated point; a different construction or transmitted identity may do so.',editorial_notes='Lexicographic Batch 02: source-aware explanatory prose; formula tables preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot') AND section_key='terminology';
UPDATE term_article_sections SET heading='Distinguishing historically named Lots',body='Names such as Love, Necessity, Marriage, Courage and Substance recur in different source traditions. The name alone is insufficient to identify a particular construction: the factors, their order, any reversal by sect and the specified starting point must also agree.',editorial_notes='Lexicographic Batch 02: source-aware explanatory prose; formula tables preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot') AND section_key='name-not-identity';
UPDATE term_article_sections SET heading='Formula transmission',body='The order of the factors can vary by author, even when the lot bears the same name. Some formulas keep the same order in day and night figures, while others reverse it or substitute another significator. The source-specific formula tables distinguish these constructions without treating any one as universal.',editorial_notes='Lexicographic Batch 02: source-aware explanatory prose; formula tables preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot') AND section_key='formula-source';
UPDATE term_article_sections SET heading='A timing testimony in Abū Maʿshar',body='Abū Maʿshar attributes this lot to Hermes. He relates the timing testimony to Jupiter arriving at, or strongly aspecting, the calculated degree, and explicitly restricts its use to a nativity that already indicates marriage. This is his transmitted judgment, not a general rule for every historical marriage lot (VIII.4.43).',editorial_notes='Lexicographic Batch 02: source-aware explanatory prose; formula tables preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='hermes-lot-of-time-of-marriage') AND section_key='formula';
UPDATE term_article_sections SET heading='Saturn and Jupiter in the Hermetic account',body='Abū Maʿshar explains the use of Saturn and Jupiter by reference to the two superior planets, generation and growth. He attributes the Saturn-to-Jupiter calculation to Hermes and the earlier authorities (Great Introduction VIII.4.11); the competing Wālīs construction is shown separately in the formula table.',editorial_notes='Lexicographic Batch 02: source-aware explanatory prose; formula tables preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-siblings') AND section_key='formula';
UPDATE term_article_sections SET heading='Brothers and their number',body='The historical heading refers to brothers, but Abū Maʿshar also discusses brothers and sisters when explaining the lot''s use. He gives the Lot of the Number of Brothers a separate construction in VIII.4.12; it is not merely another label for the present lot.',editorial_notes='Lexicographic Batch 02: source-aware explanatory prose; formula tables preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-siblings') AND section_key='identity';
UPDATE term_article_sections SET heading='The formula transmitted under Wālīs',body='Abū Maʿshar records a report by Zādān Farrūkh attributing a Mercury-to-Jupiter construction to Wālīs, while expressly preferring the Saturn-to-Jupiter formula associated with Hermes (VIII.4.11). The difference is in the starting factor, not in whether the nocturnal formula reverses.',editorial_notes='Lexicographic Batch 02: source-aware explanatory prose; formula tables preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-siblings') AND section_key='variant';
UPDATE term_article_sections SET heading='The lots distinguished in the fifth place',body='Abū Maʿshar distinguishes the general lot of children from another lot concerning their time and number, as well as from separate lots for male and female children. These have different planetary factors; they are not interchangeable expressions for the same construction (Great Introduction VIII.4.22–4.26).',editorial_notes='Lexicographic Batch 02: source-aware explanatory prose; formula tables preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-children') AND section_key='formula';
UPDATE term_article_sections SET heading='A sect-dependent and a fixed construction',body='Abū Maʿshar prefers the Hermetic construction that reverses the Jupiter–Saturn interval by night. He also reports Tawfīl''s calculation from Jupiter to Saturn in both day and night figures, and explicitly judges the first construction preferable (VIII.4.22).',editorial_notes='Lexicographic Batch 02: source-aware explanatory prose; formula tables preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-children') AND section_key='variants';
UPDATE term_article_sections SET heading='Moon and Mercury as indicators',body='Abū Maʿshar relates the Moon and Mercury to changeable human relations and describes this lot as concerned with friends and brothers. He considers the condition of both the lot and its ruler and distinguishes its comprehensive subject matter from the more limited friendship indications of Mercury''s planetary lot (Great Introduction VIII.4.77).',editorial_notes='Lexicographic Batch 02: source-aware explanatory prose; formula tables preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-friends') AND section_key='formula';
UPDATE term_article_sections SET heading='Two exaltation degrees',body='In Abū Maʿshar''s method the solar arc ends at 19° Aries by day, while the lunar arc ends at 3° Taurus by night. Both intervals are projected from the Ascendant. He judges the resulting lot in relation to the Midheaven and the condition of the planets associated with it (Great Introduction VIII.4.59).',editorial_notes='Lexicographic Batch 02: source-aware explanatory prose; formula tables preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-rank') AND section_key='formula';
UPDATE term_article_sections SET heading='The Moon and Venus; a nocturnal variant',body='Abū Maʿshar prefers the Hermetic Moon-to-Venus construction unchanged by sect, relating the pair to his account of female children. He also records Tawfīl''s alternative, which takes the same interval by day but reverses it by night (Great Introduction VIII.4.25). The displayed table retains the preferred Hermetic form.',editorial_notes='Lexicographic Batch 02: source-aware explanatory prose; formula tables preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-daughters') AND section_key='distinct';
UPDATE term_article_sections SET heading='The Moon and Jupiter; alternative transmissions',body='Abū Maʿshar prefers the Hermetic Moon-to-Jupiter construction. He also reports a Persian Moon-to-Saturn calculation that reverses by sect and a fixed Moon-to-Saturn form attributed to Tawfīl (Great Introduction VIII.4.24). These alternative constructions should not be confused with the general Lot of Children.',editorial_notes='Lexicographic Batch 02: source-aware explanatory prose; formula tables preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-sons') AND section_key='distinct';
UPDATE term_article_sections SET heading='Lot and Part of Fortune',body='Lot of Fortune and Part of Fortune are alternate English names for the corresponding lunar point in the same source tradition. Terminological equivalence does not settle the separate historical question of whether the luminary interval reverses at night.',editorial_notes='Lexicographic Batch 02: source-aware explanatory prose; formula tables preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-fortune') AND section_key='part-of-fortune';
UPDATE term_article_sections SET heading='The nocturnal formula in different authorities',body='Abū Maʿshar uses a sect-reversed luminary interval, while al-Bīrūnī (§475) explicitly reports an unreversed Ptolemaic procedure and the alternative nocturnal reversal. A Lot of Fortune calculation must therefore identify the author or procedure used, particularly when comparing natal figures across traditions.',editorial_notes='Lexicographic Batch 02: source-aware explanatory prose; formula tables preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-fortune') AND section_key='source-formula';
UPDATE term_article_sections SET heading='Substance and the second place',body='Bonatti''s construction links the ruler of the second place with the degree of that place, taking the resulting interval from the Ascendant. It makes a specific relation to resources and livelihood; this calculated point is distinct from both the second place itself and the broader assessment of material affairs in a nativity.',editorial_notes='Lexicographic Batch 02: source-aware explanatory prose; formula tables preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-substance') AND section_key='scope';
UPDATE term_article_sections SET heading='Fortune''s solar counterpart',body='Abū Maʿshar sets Absence opposite Fortune within his paired luminary lots and also calls it the Lot of the Sun. He records disagreement over which lot should bear the solar and lunar names. The source''s name and luminary order are both needed to identify the construction reliably (Great Introduction VIII.3).',editorial_notes='Lexicographic Batch 02: source-aware explanatory prose; formula tables preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-absence') AND section_key='source-formula';
UPDATE term_article_sections SET heading='The Egyptian construction',body='Abū Maʿshar attributes this lot to Egyptian authorities, using Mars and the degree of the third place without sect reversal (Great Introduction VIII.5.8). He lists it alongside a differently constructed Persian lot and subsequently discusses the two together as testimonies concerning necessity and delay.',editorial_notes='Lexicographic Batch 02: source-aware explanatory prose; formula tables preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='egyptian-lot-of-necessity') AND section_key='formula';
UPDATE term_article_sections SET heading='The Persian construction',body='Abū Maʿshar attributes this second necessity lot to Persian authorities. The interval extends from the Lot of Love and Familiarity to Mercury without reversal by sect (Great Introduction VIII.5.9). He treats it alongside, but does not identify it with, the Egyptian construction.',editorial_notes='Lexicographic Batch 02: source-aware explanatory prose; formula tables preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='persian-lot-of-necessity') AND section_key='formula';
UPDATE term_article_sections SET heading='Zodiacal interval and projection',body='For Asc + B − A, the directed zodiacal interval from A to B is added to the Ascendant''s longitude, reducing the result to the 360° circle. A source may specify another projection point or reverse A and B at night, but the operation remains the projection of an interval.',editorial_notes='Lexicographic Batch 02: source-aware explanatory prose; formula tables preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-extraction') AND section_key='mechanics';
UPDATE term_article_sections SET heading='The seven planetary lots',body='The sevenfold class has two luminary lots and five associated with the remaining planets. Their constructions differ: in Abū Maʿshar some later planetary lots use Fortune or Absence as an ingredient rather than only the corresponding planet''s own longitude (Great Introduction VIII.3.12–3.16).',editorial_notes='Lexicographic Batch 02: source-aware explanatory prose; formula tables preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='planetary-lots') AND section_key='seven-members';
UPDATE term_article_sections SET heading='Similar names in different source traditions',body='An association with Venus, desire or love does not identify all similarly named lots. Abū Maʿshar''s Venus-associated planetary lot is transmitted in his sevenfold scheme; other Lots of Eros have different formula traditions. They remain distinct unless the sources establish correspondence.',editorial_notes='Lexicographic Batch 02: source-aware explanatory prose; formula tables preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='planetary-lots') AND section_key='historical-identity';
